insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('fa76d3d7-e172-5539-9535-c0514cd7598a','1. Freischalten. 2. Gegen Wiedereinschalten sichern. 3. Spannungsfreiheit allseitig feststellen. 4. Erden und kurzschließen. 5. Benachbarte, unter Spannung stehende Teile abdecken oder abschranken. Die Reihenfolge ist zwingend, weil jeder Schritt den nächsten erst sicher macht: Ohne Freischalten wäre jede weitere Handlung an spannungsführenden Teilen; ohne Sicherung gegen Wiedereinschalten könnte die Anlage während der Arbeit erneut unter Spannung gesetzt werden; erst nach dem Feststellen der Spannungsfreiheit darf geerdet werden, weil ein Erden unter Spannung einen Kurzschluss mit Lichtbogen auslösen würde. Das Abdecken benachbarter Teile schützt zuletzt vor unbeabsichtigtem Berühren im Arbeitsumfeld.','{"max_punkte": 7, "kriterien": [{"id": "k1", "beschreibung": "Regel 1 Freischalten genannt", "punkte": 1}, {"id": "k2", "beschreibung": "Regel 2 gegen Wiedereinschalten sichern genannt", "punkte": 1}, {"id": "k3", "beschreibung": "Regel 3 Spannungsfreiheit feststellen genannt", "punkte": 1}, {"id": "k4", "beschreibung": "Regel 4 Erden und Kurzschließen genannt", "punkte": 1}, {"id": "k5", "beschreibung": "Regel 5 Abdecken/Abschranken genannt", "punkte": 1}, {"id": "k6", "beschreibung": "Reihenfolge vollständig korrekt", "punkte": 1}, {"id": "k7", "beschreibung": "Begründung, dass jeder Schritt den nächsten absichert", "punkte": 1}], "akzeptierte_synonyme": ["allpolig trennen", "Verbotsschild anbringen", "zweipoliger Spannungsprüfer", "kurzschließen und erden"], "haeufige_fehler": ["Erden vor dem Feststellen der Spannungsfreiheit", "Weglassen der Sicherung gegen Wiedereinschalten"]}'::jsonb,7) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('9e9e49e3-5690-5a3d-b1ec-48b3a3d8cf7f','38a8a65a-1c35-53bf-a3ef-dbcfcca4e66d','freitext','Erklären Sie den Unterschied zwischen Reihen- und Parallelschaltung von Widerständen anhand von Strom, Spannung und Gesamtwiderstand.',2,'entwurf',true,false,2,null,false,'EBT-GR-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('9e9e49e3-5690-5a3d-b1ec-48b3a3d8cf7f','In der Reihenschaltung fließt durch alle Widerstände derselbe Strom. Die Teilspannungen addieren sich zur Gesamtspannung, und der Gesamtwiderstand ist die Summe der Einzelwiderstände; er ist damit größer als jeder Einzelwiderstand. In der Parallelschaltung liegt an allen Widerständen dieselbe Spannung an. Die Zweigströme addieren sich zum Gesamtstrom, und der Gesamtwiderstand ist kleiner als der kleinste Einzelwiderstand, weil sich die Leitwerte addieren.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Reihenschaltung: Strom überall gleich", "punkte": 1}, {"id": "k2", "beschreibung": "Reihenschaltung: Teilspannungen addieren sich", "punkte": 1}, {"id": "k3", "beschreibung": "Reihenschaltung: Gesamtwiderstand ist die Summe", "punkte": 1}, {"id": "k4", "beschreibung": "Parallelschaltung: Spannung überall gleich", "punkte": 1}, {"id": "k5", "beschreibung": "Parallelschaltung: Zweigströme addieren sich", "punkte": 1}, {"id": "k6", "beschreibung": "Parallelschaltung: Gesamtwiderstand kleiner als kleinster Einzelwiderstand", "punkte": 1}], "akzeptierte_synonyme": ["Spannungsteiler", "Stromteiler", "Leitwerte addieren sich"], "haeufige_fehler": ["Vertauschen der Regeln für Strom und Spannung"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('7eada41c-88a4-57c0-ac20-536a7b0b3620','4951c918-0234-5056-a3f3-8ae3555d61b3','freitext','Ein Drehstrommotor an einer Förderanlage läuft nach dem Einschalten nicht an, brummt aber hörbar. Beschreiben Sie ein systematisches Vorgehen zur Fehlersuche.',3,'entwurf',true,false,2,null,false,'EBT-IN-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('7eada41c-88a4-57c0-ac20-536a7b0b3620','Das Brummen ohne Anlauf deutet auf den Ausfall eines Außenleiters hin, der Motor läuft dann nur zweiphasig. Vorgehen: 1. Anlage sicher stillsetzen, Motorschutz zurücksetzen und den Auslösegrund dokumentieren. 2. Sichtprüfung von Klemmkasten, Leitungen und Anschlüssen auf lose oder verschmorte Stellen. 3. Sicherungen und Motorschutzschalter auf Auslösung eines einzelnen Außenleiters prüfen. 4. Im freigeschalteten Zustand die Wicklungen auf Durchgang und gleichmäßige Widerstandswerte sowie gegen den Schutzleiter auf Isolation messen. 5. Mechanik prüfen: blockierte Last, schwergängiges Lager oder festsitzende Bremse können den Anlauf ebenfalls verhindern. 6. Fehler beheben, Schutzeinrichtungen prüfen, Probelauf durchführen und Ergebnis dokumentieren. Alle Messungen an spannungsführenden Teilen nur als Elektrofachkraft und nach den fünf Sicherheitsregeln.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Erkennt Phasenausfall als naheliegende Ursache", "punkte": 1}, {"id": "k2", "beschreibung": "Sichere Stillsetzung und Beachtung der Sicherheitsregeln", "punkte": 1}, {"id": "k3", "beschreibung": "Sichtprüfung Anschlüsse und Klemmkasten", "punkte": 1}, {"id": "k4", "beschreibung": "Prüfung von Sicherungen bzw. Motorschutz", "punkte": 1}, {"id": "k5", "beschreibung": "Messung von Wicklungsdurchgang und Isolation", "punkte": 1}, {"id": "k6", "beschreibung": "Prüfung der Mechanik und abschließender Probelauf mit Dokumentation", "punkte": 1}], "akzeptierte_synonyme": ["zweiphasiger Lauf", "Phasenausfall", "Wicklungsschluss", "blockierte Last"], "haeufige_fehler": ["Messen unter Spannung ohne Befähigung", "Wiederholtes Einschalten ohne Ursachenklärung"]}'::jsonb,6) on conflict (frage_id) do nothing;
