insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('33f9c610-9f7c-57e4-9184-fa2a55022f3c','1. Sendung annehmen und die Begleitpapiere prüfen: Ist die Lieferung für den Betrieb bestimmt, liegt eine Bestellung vor. 2. Äußere Prüfung der Verpackung und Paletten auf Beschädigung, Feuchtigkeit oder Bruch; Auffälligkeiten sofort auf dem Frachtpapier vermerken. 3. Mengenprüfung: gelieferte Menge mit Lieferschein und Bestellung abgleichen. 4. Qualitäts- beziehungsweise Identitätsprüfung: Artikelnummer, Ausführung und, wo vorgesehen, Chargen- oder Haltbarkeitsangaben kontrollieren. 5. Abweichungen dokumentieren und der zuständigen Stelle melden. 6. Ware im System erfassen, buchen und mit Lagerplatz kennzeichnen. 7. Einlagern nach den betrieblichen Vorgaben, etwa unter Beachtung von FIFO, Gewicht und Zugriffshäufigkeit.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Prüfung der Begleitpapiere und Zuordnung zur Bestellung", "punkte": 1}, {"id": "k2", "beschreibung": "Äußere Zustandsprüfung mit Vermerk bei Schäden", "punkte": 1}, {"id": "k3", "beschreibung": "Mengenprüfung gegen Lieferschein/Bestellung", "punkte": 1}, {"id": "k4", "beschreibung": "Identitäts- bzw. Qualitätsprüfung des Artikels", "punkte": 1}, {"id": "k5", "beschreibung": "Dokumentation und Meldung von Abweichungen", "punkte": 1}, {"id": "k6", "beschreibung": "Buchung im System und sachgerechte Einlagerung", "punkte": 1}], "akzeptierte_synonyme": ["Vorbehalt auf dem Frachtbrief", "Identitätskontrolle", "Buchung im Warenwirtschaftssystem", "FIFO beachten"], "haeufige_fehler": ["Einlagerung vor der Prüfung", "Schadensvermerk erst nach Abfahrt des Fahrers"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('48872382-e83b-5d5b-826d-79b2baf732be','0a87fd9a-f356-5994-a4fe-6f981616a35a','freitext','Erklären Sie, warum eine ungesicherte Ladung auch bei geringem Gewicht gefährlich ist, und nennen Sie drei Hilfsmittel der Ladungssicherung.',2,'entwurf',true,false,2,null,false,'FLA-TR-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('48872382-e83b-5d5b-826d-79b2baf732be','Bei einer Vollbremsung oder einem Ausweichmanöver wirken auf die Ladung erhebliche Kräfte; ein Gegenstand von wenigen Kilogramm entwickelt dabei ein Vielfaches seines Gewichts als Wucht und kann Fahrzeuginsassen schwer verletzen oder das Fahrzeug destabilisieren. Deshalb ist jede Ladung unabhängig vom Gewicht zu sichern. Hilfsmittel: Zurrgurte mit passender Zurrkraft, rutschhemmende Matten zur Erhöhung der Reibung, Kantenschutz zum Schutz von Gurt und Ladung, Sperrbalken oder Ladungssicherungsnetze sowie formschlüssiges Verstauen bis an die Bordwände.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Erklärt die Massenkräfte bei Bremsung bzw. Ausweichen", "punkte": 1}, {"id": "k2", "beschreibung": "Zieht daraus die Folgerung, dass auch leichte Ladung zu sichern ist", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt ein zutreffendes Hilfsmittel", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt ein zweites zutreffendes Hilfsmittel", "punkte": 1}, {"id": "k5", "beschreibung": "Nennt ein drittes zutreffendes Hilfsmittel", "punkte": 1}], "akzeptierte_synonyme": ["Antirutschmatte", "Zurrgurt", "Sperrstange", "formschlüssig verstauen", "Kantenschutz"], "haeufige_fehler": ["Annahme, geringes Gewicht brauche keine Sicherung", "Nennung von Verpackung als alleiniger Sicherung"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('8b756719-a854-5656-8865-5e5f7bebc4b9','fafa72b0-9776-55b8-aa89-d1573c4900cc','freitext','Bei einer Inventur stellen Sie fest, dass von einem Artikel weniger Stück vorhanden sind als im System gebucht. Nennen Sie drei mögliche Ursachen und beschreiben Sie, wie Sie vorgehen.',3,'entwurf',true,false,2,null,false,'FLA-WISO-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('8b756719-a854-5656-8865-5e5f7bebc4b9','Mögliche Ursachen: Entnahme ohne Buchung, Fehlbuchung oder Buchung auf den falschen Artikel, Kommissionierfehler mit zu hoher Auslieferung, Verwechslung ähnlicher Artikel, Einlagerung auf einem anderen Lagerplatz, Schwund durch Beschädigung oder Diebstahl. Vorgehen: Zuerst nachzählen und den benachbarten Lagerplatz sowie ähnliche Artikelnummern prüfen, um Verwechslungen auszuschließen. Dann die Buchungshistorie des Artikels prüfen und mit Lieferscheinen und Kommissionieraufträgen abgleichen. Bleibt die Differenz bestehen, wird sie dokumentiert, der Vorgesetzten Stelle gemeldet und nach betrieblicher Regelung korrigiert. Anschließend sollte die Ursache abgestellt werden, etwa durch Schulung, klarere Kennzeichnung oder Scannen bei jeder Entnahme.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Nennt eine plausible Ursache", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt eine zweite plausible Ursache", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt eine dritte plausible Ursache", "punkte": 1}, {"id": "k4", "beschreibung": "Nachzählen und Prüfen benachbarter Plätze/ähnlicher Artikel", "punkte": 1}, {"id": "k5", "beschreibung": "Prüfen der Buchungshistorie und Belege", "punkte": 1}, {"id": "k6", "beschreibung": "Dokumentation, Meldung und Maßnahme zur Ursachenbeseitigung", "punkte": 1}], "akzeptierte_synonyme": ["Fehlbuchung", "Schwund", "Verwechslung", "Buchungshistorie", "Scannpflicht"], "haeufige_fehler": ["Sofortiges Anpassen des Systembestands ohne Ursachensuche", "Unterstellen von Diebstahl ohne Prüfung"]}'::jsonb,6) on conflict (frage_id) do nothing;
