insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('3e2e8da5-fc6d-55a0-8896-33437ef25e92','34296c69-a9b0-55d8-ac71-9750251b8c7b','p = 60 bar',true,'A = 20 cm² = 2 000 mm². p = F / A = 12 000 N / 2 000 mm² = 6 N/mm² = 60 bar.',1) on conflict (id) do nothing;
