insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('022f4982-e7ed-5ab6-8cb9-9cc1282ea8e6','81b6e72e-7cfd-5d58-85db-ee8a052b0cc2','freitext','Nennen Sie drei Aufgaben des Kühlschmierstoffs bei der spanenden Bearbeitung und erklären Sie, welche Folgen fehlende Kühlschmierung für Werkzeug und Werkstück hat.',2,'entwurf',true,false,2,null,false,'IM-FT-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('022f4982-e7ed-5ab6-8cb9-9cc1282ea8e6','Aufgaben: 1. Kühlen – die Prozesswärme wird abgeführt, Werkzeug und Werkstück bleiben maßhaltig. 2. Schmieren – die Reibung zwischen Span, Spanfläche und Werkstück wird verringert. 3. Spülen und Reinigen – Späne werden aus der Wirkzone transportiert; zusätzlich schützt der Film vor Korrosion. Fehlt die Kühlschmierung, steigt die Temperatur an der Schneide stark an. Das Werkzeug verschleißt schneller, kann seine Härte verlieren und ausfallen. Am Werkstück entstehen schlechtere Oberflächen, Aufbauschneiden, Maßabweichungen durch Wärmedehnung und im Extremfall Gefügeveränderungen der Randschicht.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Nennt das Kühlen als Aufgabe", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt das Schmieren bzw. die Reibungsminderung", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt den Spänetransport bzw. das Spülen", "punkte": 1}, {"id": "k4", "beschreibung": "Beschreibt die Folge für das Werkzeug (erhöhter Verschleiß, Härteverlust)", "punkte": 1}, {"id": "k5", "beschreibung": "Beschreibt die Folge für das Werkstück (Oberfläche, Maßhaltigkeit)", "punkte": 1}], "akzeptierte_synonyme": ["Wärmeabfuhr", "Reibung senken", "Späne abtransportieren", "Standzeit sinkt", "Aufbauschneide"], "haeufige_fehler": ["Nennung nur einer Aufgabe", "Verwechslung von Kühlschmierstoff und Hydrauliköl"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('58933774-f960-5703-92ab-a019331d4305','6b154eda-0a54-55b7-89ff-418344a84673','freitext','An einer Produktionsanlage tritt an einer Hydraulikleitung Öl aus. Beschreiben Sie Ihr Vorgehen von der Feststellung bis zur Wiederinbetriebnahme.',3,'entwurf',true,false,2,null,false,'IM-BT-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('58933774-f960-5703-92ab-a019331d4305','1. Anlage stillsetzen, drucklos machen und gegen Wiedereinschalten sichern; die Stelle gegen Rutschgefahr absperren. 2. Austretendes Öl mit Bindemittel aufnehmen und als gefährlichen Abfall entsorgen. 3. Störung melden und dokumentieren. 4. Ursache eingrenzen: Leitung, Verschraubung, Dichtung oder Schlauch prüfen; auf Scheuerstellen und Alterung achten. 5. Schadhaftes Teil durch ein zugelassenes Ersatzteil gleicher Druckstufe ersetzen. 6. System wieder befüllen, entlüften und den Ölstand prüfen. 7. Dichtheitsprüfung mit Probelauf bei geringem Druck, danach Freigabe und Eintrag in die Instandhaltungsdokumentation.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Stillsetzen, drucklos machen, gegen Wiedereinschalten sichern", "punkte": 1}, {"id": "k2", "beschreibung": "Umweltgerechtes Aufnehmen und Entsorgen des Öls", "punkte": 1}, {"id": "k3", "beschreibung": "Meldung und Dokumentation der Störung", "punkte": 1}, {"id": "k4", "beschreibung": "Systematische Ursachensuche an Leitung/Verschraubung/Dichtung", "punkte": 1}, {"id": "k5", "beschreibung": "Instandsetzung mit geeignetem Ersatzteil, Befüllen und Entlüften", "punkte": 1}, {"id": "k6", "beschreibung": "Funktions- bzw. Dichtheitsprüfung vor der Freigabe", "punkte": 1}], "akzeptierte_synonyme": ["LOTO", "Ölbindemittel", "Sonderabfall", "Probelauf", "Instandhaltungsprotokoll"], "haeufige_fehler": ["Reparatur unter Druck", "Entsorgung über den Restmüll", "Wiederinbetriebnahme ohne Dichtheitsprüfung"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('9e875e94-5b4a-5f86-a842-c490298cad08','2fc43632-8960-54cc-8d4d-3c271d758abe','freitext','Erklären Sie, warum ein Betrieb Fertigungsaufträge in einem Arbeitsplan dokumentiert. Nennen Sie mindestens drei Angaben, die ein Arbeitsplan enthält.',2,'entwurf',true,false,2,null,false,'IM-WISO-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('9e875e94-5b4a-5f86-a842-c490298cad08','Der Arbeitsplan legt fest, wie ein Auftrag reproduzierbar gefertigt wird. Er sichert gleichbleibende Qualität, macht Kalkulation und Terminplanung möglich und ermöglicht es, dass verschiedene Mitarbeiter denselben Auftrag mit gleichem Ergebnis ausführen. Typische Angaben: Reihenfolge der Arbeitsgänge, eingesetzte Maschine oder Arbeitsplatz, Werkzeuge und Spannmittel, Vorgabezeiten je Arbeitsgang, Prüfmerkmale und Prüfmittel, Werkstoff und Rohteilmaße sowie der Bezug zur Zeichnungsnummer.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Nennt Reproduzierbarkeit bzw. gleichbleibende Qualität als Zweck", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt Kalkulation oder Terminplanung als Zweck", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt eine zutreffende Angabe des Arbeitsplans", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt eine zweite zutreffende Angabe", "punkte": 1}, {"id": "k5", "beschreibung": "Nennt eine dritte zutreffende Angabe", "punkte": 1}], "akzeptierte_synonyme": ["Arbeitsgangfolge", "Vorgabezeit", "Betriebsmittel", "Prüfplanbezug"], "haeufige_fehler": ["Verwechslung von Arbeitsplan und Stückliste"]}'::jsonb,5) on conflict (frage_id) do nothing;
