insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('9232b9d9-dd78-5930-8f84-c0a5c2387c74','d90b336a-afd9-50e4-8a1c-970554364401','mc','Ein Kunde beauftragt eine Inspektion. Während der Arbeit wird ein zusätzlicher, kostenpflichtiger Mangel festgestellt. Wie ist zu verfahren?',2,'entwurf',true,false,2,null,false,'KFZ-WISO-BW-101') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('bf8b0713-dd02-58c7-93ea-0d7707ebb60c','9232b9d9-dd78-5930-8f84-c0a5c2387c74','Den Kunden informieren und die Zustimmung einholen, bevor die zusätzliche Arbeit ausgeführt wird',true,'Der Auftragsumfang wird vom Kunden bestimmt; Mehrarbeit bedarf seiner Zustimmung, die dokumentiert werden sollte.',1) on conflict (id) do nothing;
