insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('39fc38f8-eafd-5233-b255-b809fb28b7e2','974f1aa9-b197-5351-ad7d-69e386b0205e','freitext','Ein Kunde beschreibt, dass das Bremspedal weich ist und sich bis fast zum Bodenblech durchtreten lässt. Nennen Sie drei mögliche Ursachen und beschreiben Sie, wie Sie vorgehen.',2,'entwurf',true,false,2,null,false,'KFZ-FZ-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('39fc38f8-eafd-5233-b255-b809fb28b7e2','Mögliche Ursachen: Luft im Bremssystem, Leckage an Leitung, Radbremszylinder oder Bremssattel, Defekt im Hauptbremszylinder (innere Undichtigkeit), stark abgenutzte Beläge oder überhitzte Bremsflüssigkeit mit Dampfblasenbildung. Vorgehen: Zuerst das Fahrzeug als möglicherweise nicht verkehrssicher behandeln und den Kunden darauf hinweisen. Dann Flüssigkeitsstand und Sichtprüfung des gesamten Systems auf Leckagen, Prüfung der Beläge und Scheiben, Prüfung des Siedepunkts der Bremsflüssigkeit. Ergibt sich keine äußere Leckage, ist der Hauptbremszylinder zu prüfen. Nach der Instandsetzung wird das System entlüftet, der Pedalweg kontrolliert und eine Bremsprüfung durchgeführt; das Ergebnis wird dokumentiert.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Nennt Luft im System als Ursache", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt eine Leckage als Ursache", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt eine dritte plausible Ursache", "punkte": 1}, {"id": "k4", "beschreibung": "Weist auf die eingeschränkte Verkehrssicherheit hin", "punkte": 1}, {"id": "k5", "beschreibung": "Beschreibt systematische Sicht- und Funktionsprüfung", "punkte": 1}, {"id": "k6", "beschreibung": "Nennt Entlüften und abschließende Bremsprüfung mit Dokumentation", "punkte": 1}], "akzeptierte_synonyme": ["Dampfblasenbildung", "Hauptbremszylinder undicht", "Bremsleitung porös", "Siedepunktmessung"], "haeufige_fehler": ["Nur Nachfüllen der Bremsflüssigkeit ohne Ursachensuche", "Fahrzeugrückgabe ohne Bremsprüfung"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('0809eb66-5955-5673-b2f6-2e0d18eb1f72','d29bef48-5c42-52a5-a9de-5e5a191c18c3','freitext','Beschreiben Sie die Schritte einer systematischen Fehlersuche an einem Fahrzeug, von der Kundenannahme bis zur Übergabe.',3,'entwurf',true,false,2,null,false,'KFZ-SE-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('0809eb66-5955-5673-b2f6-2e0d18eb1f72','1. Kundenbefragung: Wann tritt der Fehler auf, bei welcher Temperatur, Drehzahl oder Fahrsituation, seit wann. 2. Fehler nachvollziehen, wenn möglich durch Probefahrt oder Nachstellen der Bedingungen. 3. Sichtprüfung von Bauteilen, Leitungen und Steckverbindungen. 4. Fehlerspeicher auslesen und Einträge zusammen mit Umgebungsbedingungen bewerten. 5. Anhand von Schaltplan und geführter Fehlersuche gezielt messen und den Fehler eingrenzen, statt Teile zu tauschen. 6. Ursache beheben und die Reparatur dokumentieren. 7. Fehlerspeicher löschen, Funktion durch Probefahrt und erneutes Auslesen prüfen. 8. Fahrzeug übergeben und dem Kunden Ursache, Maßnahme und gegebenenfalls weitere Empfehlungen erklären.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Kundenbefragung und Erfassung der Fehlerbedingungen", "punkte": 1}, {"id": "k2", "beschreibung": "Fehler nachvollziehen bzw. Sichtprüfung", "punkte": 1}, {"id": "k3", "beschreibung": "Fehlerspeicher auslesen und bewerten", "punkte": 1}, {"id": "k4", "beschreibung": "Gezieltes Messen nach Schaltplan statt Teiletausch", "punkte": 1}, {"id": "k5", "beschreibung": "Instandsetzung mit Dokumentation", "punkte": 1}, {"id": "k6", "beschreibung": "Funktionsprüfung und Kundenübergabe mit Erklärung", "punkte": 1}], "akzeptierte_synonyme": ["geführte Fehlersuche", "Umgebungsbedingungen", "Probefahrt", "Messwerte im Istzustand"], "haeufige_fehler": ["Teiletausch auf Verdacht", "Löschen des Fehlerspeichers ohne Ursachenklärung"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('fb35ae0a-278e-5a88-bfad-10717a85e887','b54780d3-3b48-5642-955b-fb341b86f432','freitext','Nennen Sie vier Abfallarten, die in einer Kfz-Werkstatt getrennt zu erfassen sind, und begründen Sie, warum eine Vermischung unzulässig ist.',2,'entwurf',true,false,2,null,false,'KFZ-WISO-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('fb35ae0a-278e-5a88-bfad-10717a85e887','Getrennt zu erfassen sind unter anderem: Altöl, Ölfilter und ölverschmutzte Betriebsmittel, Bremsflüssigkeit, Kühlerfrostschutzmittel, Altbatterien, Altreifen sowie Lösemittel- und Lackreste. Eine Vermischung ist unzulässig, weil sich vermischte Abfälle nicht mehr sortenrein verwerten lassen und die gesamte Menge dann als gefährlicher Abfall entsorgt werden muss. Außerdem können sich unverträgliche Stoffe gegenseitig gefährlich beeinflussen, und der gesetzlich geforderte Entsorgungsnachweis wäre nicht mehr führbar.','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Nennt Altöl bzw. ölverschmutzte Betriebsmittel", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt eine zweite zutreffende Abfallart", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt eine dritte zutreffende Abfallart", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt eine vierte zutreffende Abfallart", "punkte": 1}, {"id": "k5", "beschreibung": "Begründet mit der Verwertbarkeit bzw. Sortenreinheit", "punkte": 1}, {"id": "k6", "beschreibung": "Nennt rechtliche Nachweispflicht oder Gefährdungsaspekt", "punkte": 1}], "akzeptierte_synonyme": ["Sonderabfall", "gefährlicher Abfall", "Entsorgungsnachweis", "sortenrein"], "haeufige_fehler": ["Nennung von Hausmüll als getrennte Sonderabfallart", "Behauptung, geringe Mengen dürften vermischt werden"]}'::jsonb,6) on conflict (frage_id) do nothing;
