insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('42ffc74c-ecfd-59b5-9dbd-f311ce2027f1','fac1c582-1743-5a5a-8223-0c988536b786','Breite Strichpunktlinie',false,'Die breite Strichpunktlinie kennzeichnet Bereiche mit besonderer Behandlung, etwa gehärtete Flächen.',3) on conflict (id) do nothing;
