insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('09211534-a7c7-512a-84f2-a4394b693b2f','fd6e238a-8aa0-5dee-85a6-aa9c8db09969','mc','Ein Bauteil ist in der europäischen Projektionsmethode dargestellt. Welche Ansicht wird unter der Vorderansicht gezeichnet?',2,'entwurf',true,false,2,null,false,'PT-TU-102') on conflict (id) do nothing;
