insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('404b12a7-567a-50ae-80b2-7847ff97d218','09211534-a7c7-512a-84f2-a4394b693b2f','Die Ansicht von rechts',false,'Die Ansicht von rechts steht links neben der Vorderansicht.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('66c413a3-b8d5-534d-bd3f-3bd29af85f02','09211534-a7c7-512a-84f2-a4394b693b2f','Die Draufsicht',true,'In Methode 1 wird das Bauteil weggeklappt: Was man von oben sieht, erscheint unterhalb der Vorderansicht.',4) on conflict (id) do nothing;
