insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('9f24fc94-c90c-5704-96e7-51d1f88c3f01','de9d7289-1a5b-530d-9205-e6d347d1fcde','Halbschnitt',true,'Der Halbschnitt zeigt bei symmetrischen Bauteilen eine Hälfte in Ansicht und eine Hälfte im Schnitt.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('c7b623b7-fc8f-5f33-a2e9-491a94f48693','de9d7289-1a5b-530d-9205-e6d347d1fcde','Vollschnitt',false,'Beim Vollschnitt wird das gesamte Bauteil durchgeschnitten dargestellt.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('67ed04a0-852f-5a7c-8c48-ca412d5652b0','de9d7289-1a5b-530d-9205-e6d347d1fcde','Profilschnitt',false,'Ein Profilschnitt ist keine genormte Schnittart der technischen Zeichnung.',4) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('32f53d89-b175-5a80-988e-90d99a9f92b9','de9d7289-1a5b-530d-9205-e6d347d1fcde','Teilschnitt',false,'Der Teilschnitt öffnet nur einen begrenzten Bereich und wird von einer Freihandlinie begrenzt.',5) on conflict (id) do nothing;
