insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('bce51c85-7d30-5720-ae9d-329e5f822310','6a4d3d80-bb51-511f-b635-866b4176fdb2','Das Durchmesserzeichen entfällt, wenn die Stufe geschnitten dargestellt ist.',false,'Die Schnittdarstellung ändert die Bemaßungsregel nicht.',2) on conflict (id) do nothing;
