insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('542264b8-9757-5237-ba39-c26ed25632ea','9a1d04e0-0e2e-50d2-97fe-b371ec4915d1','F ≈ 2 356 N',false,'Hier wurde die Fläche verdoppelt.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('166b0a20-e733-538a-b3c3-b37bb44361fe','9a1d04e0-0e2e-50d2-97fe-b371ec4915d1','F ≈ 1 178 N',true,'A = π/4 × (50 mm)² = 1 963,5 mm². p = 6 bar = 0,6 N/mm². F = p × A = 0,6 N/mm² × 1 963,5 mm² ≈ 1 178 N.',2) on conflict (id) do nothing;
