insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('b03886a0-5b86-5e79-a5d0-9bb00b6429b4','68bb7fa9-25eb-5d11-81e3-a54444b61d9c','mc','Ein Werkstück mit dem Durchmesser 80 mm wird mit einer Drehzahl von 400 min⁻¹ gedreht. Wie groß ist die Schnittgeschwindigkeit?',3,'entwurf',false,false,2,null,true,'PT-RE-110') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('790eff60-5ca1-5480-8a1b-fd139d7eed76','b03886a0-5b86-5e79-a5d0-9bb00b6429b4','vc ≈ 201 m/min',false,'Hier wurde der Durchmesser verdoppelt.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('afe56511-05f5-514f-abe5-cf276646e4eb','b03886a0-5b86-5e79-a5d0-9bb00b6429b4','vc ≈ 100 m/min',true,'vc = π × d × n = 3,1416 × 0,08 m × 400 min⁻¹ ≈ 100,5 m/min.',2) on conflict (id) do nothing;
