insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('6af6ab9d-7ad5-587d-af9e-efd418da817d','fd6e238a-8aa0-5dee-85a6-aa9c8db09969','freitext','Nennen Sie vier Angaben, die im Schriftfeld einer technischen Zeichnung stehen, und erklären Sie, warum die Zeichnungsnummer für die Fertigung besonders wichtig ist.',2,'entwurf',true,false,2,null,false,'PT-TU-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('6af6ab9d-7ad5-587d-af9e-efd418da817d','Im Schriftfeld stehen unter anderem: Benennung des Teils, Zeichnungsnummer, Maßstab, Werkstoff, Ersteller und Datum, Allgemeintoleranzen sowie die Projektionsmethode. Die Zeichnungsnummer ist die eindeutige Kennung des Dokuments. Über sie werden Fertigungsauftrag, Stückliste, Prüfplan und Änderungsstand einander zugeordnet. Ohne eindeutige Zeichnungsnummer könnte nach einer Änderung ein veralteter Zeichnungsstand gefertigt werden.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Nennt zwei zutreffende Schriftfeldangaben", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt zwei weitere zutreffende Schriftfeldangaben", "punkte": 1}, {"id": "k3", "beschreibung": "Beschreibt die Zeichnungsnummer als eindeutige Kennung des Dokuments", "punkte": 1}, {"id": "k4", "beschreibung": "Stellt den Bezug zu Auftrag, Stückliste oder Änderungsstand her", "punkte": 1}], "akzeptierte_synonyme": ["Teilenummer", "Sachnummer", "Index", "Revisionsstand", "Blattnummer"], "haeufige_fehler": ["Verwechslung von Zeichnungsnummer und Auftragsnummer", "Nennung von Maßen als Schriftfeldangabe"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('e93ab3be-44a3-5d46-a67b-b2d51997da7c','82abe809-66f4-5fa2-a41a-cdee4008286c','freitext','Erklären Sie, warum ein Werkstück nach dem Härten zusätzlich angelassen wird. Gehen Sie dabei auf Härte und Zähigkeit ein.',2,'entwurf',true,false,2,null,false,'PT-WS-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('e93ab3be-44a3-5d46-a67b-b2d51997da7c','Beim Härten wird der Stahl auf Härtetemperatur erwärmt und abgeschreckt. Dabei entsteht ein sehr hartes, aber sprödes Gefüge, und es bleiben hohe innere Spannungen zurück. Ein so behandeltes Werkstück kann bei Stoßbeanspruchung reißen oder brechen. Beim anschließenden Anlassen wird das Bauteil erneut auf eine niedrigere Temperatur erwärmt und langsam abgekühlt. Dadurch bauen sich Spannungen ab, die Härte nimmt etwas ab und die Zähigkeit steigt deutlich. Über die Anlasstemperatur lässt sich einstellen, wie das Verhältnis von Härte zu Zähigkeit für den jeweiligen Einsatzfall ausfällt.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Beschreibt den Zustand nach dem Härten als hart und spröde", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt innere Spannungen bzw. Rissgefahr als Problem", "punkte": 1}, {"id": "k3", "beschreibung": "Beschreibt Anlassen als erneutes Erwärmen auf niedrigere Temperatur", "punkte": 1}, {"id": "k4", "beschreibung": "Beschreibt die Wirkung: Härte sinkt leicht, Zähigkeit steigt", "punkte": 1}], "akzeptierte_synonyme": ["Eigenspannungen", "Härtespannungen", "zäher", "weniger bruchempfindlich", "Vergüten"], "haeufige_fehler": ["Anlassen mit Normalglühen verwechselt", "Behauptung, die Härte steige durch Anlassen"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('2f553fab-99fa-5127-9122-ecc19460bc58','bf9403c9-6a63-538b-9ec6-b0718f1a5e4c','freitext','Nennen Sie drei Einflüsse, die beim Messen mit dem Messschieber zu einem falschen Messergebnis führen können, und geben Sie zu jedem Einfluss an, wie Sie ihn vermeiden.',2,'entwurf',true,false,2,null,false,'PT-PR-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('2f553fab-99fa-5127-9122-ecc19460bc58','1. Verschmutzte Messflächen oder Späne zwischen Messschenkel und Werkstück: Messflächen und Werkstück vor dem Messen reinigen. 2. Zu hoher oder ungleichmäßiger Messdruck, dadurch Verkanten der Schenkel: mit gefühlvollem, gleichmäßigem Druck messen und den Messschieber rechtwinklig ansetzen. 3. Temperaturunterschied zwischen Werkstück und Messmittel: Werkstück vor dem Messen auf Raumtemperatur bringen, Bezugstemperatur 20 °C. Weitere zulässige Antworten: Ablesefehler durch schräges Ansehen der Skala (senkrecht ablesen), beschädigte oder abgenutzte Messflächen (Messmittel prüfen und ggf. aussondern), nicht auf Null stehender Messschieber (Nullstellung vor dem Messen kontrollieren).','{"max_punkte": 6, "kriterien": [{"id": "k1", "beschreibung": "Nennt einen zutreffenden Einflussfaktor", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt die passende Vermeidungsmaßnahme dazu", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt einen zweiten zutreffenden Einflussfaktor", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt die passende Vermeidungsmaßnahme dazu", "punkte": 1}, {"id": "k5", "beschreibung": "Nennt einen dritten zutreffenden Einflussfaktor", "punkte": 1}, {"id": "k6", "beschreibung": "Nennt die passende Vermeidungsmaßnahme dazu", "punkte": 1}], "akzeptierte_synonyme": ["Verkanten", "Messkraft", "Nullpunktkontrolle", "Parallaxe", "Wärmedehnung"], "haeufige_fehler": ["Nennung von Einflüssen ohne Maßnahme", "Verwechslung von Messfehler und Werkstückfehler"]}'::jsonb,6) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('fb55236f-7a7f-5fdd-9106-073b5d357af7','685b7af8-cc0a-5c3a-9417-fdc227bce46e','freitext','Ordnen Sie die folgenden Fertigungsverfahren jeweils einer Hauptgruppe nach DIN 8580 zu und begründen Sie Ihre Zuordnung kurz: Sandgießen, Tiefziehen, Bohren, Schweißen.',2,'entwurf',true,false,2,null,false,'PT-FT-F02') on conflict (id) do nothing;
insert into normen (id,nummer,status) values ('cfcb982f-47b4-5ae6-9bf6-237e88d009e2','DIN 8580','gueltig') on conflict (id) do nothing;
insert into frage_normen (frage_id,norm_id) values ('fb55236f-7a7f-5fdd-9106-073b5d357af7','cfcb982f-47b4-5ae6-9bf6-237e88d009e2') on conflict do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('fb55236f-7a7f-5fdd-9106-073b5d357af7','Sandgießen gehört zum Urformen, weil aus formlosem Stoff erstmalig ein fester Körper mit bestimmter Form entsteht. Tiefziehen gehört zum Umformen, weil die Form eines vorhandenen Körpers plastisch geändert wird, Masse und Zusammenhalt aber erhalten bleiben. Bohren gehört zum Trennen, weil der Zusammenhalt örtlich aufgehoben und Werkstoff in Form von Spänen abgetragen wird. Schweißen gehört zum Fügen, weil zwei Teile dauerhaft und stoffschlüssig verbunden werden.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Sandgießen korrekt dem Urformen zugeordnet und begründet", "punkte": 1}, {"id": "k2", "beschreibung": "Tiefziehen korrekt dem Umformen zugeordnet und begründet", "punkte": 1}, {"id": "k3", "beschreibung": "Bohren korrekt dem Trennen zugeordnet und begründet", "punkte": 1}, {"id": "k4", "beschreibung": "Schweißen korrekt dem Fügen zugeordnet und begründet", "punkte": 1}], "akzeptierte_synonyme": ["formloser Stoff", "plastische Formänderung", "Spanen", "stoffschlüssig verbinden"], "haeufige_fehler": ["Tiefziehen dem Trennen zugeordnet", "Schweißen dem Stoffeigenschaftändern zugeordnet"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('134d0c9c-693e-52b6-b179-58b675aa3293','770eeb84-d9de-5b36-878a-b69b9024625f','freitext','Bei der fertigungsbegleitenden Prüfung stellen Sie fest, dass ein Maß seit mehreren Teilen langsam in Richtung der oberen Toleranzgrenze wandert, aber noch innerhalb der Toleranz liegt. Beschreiben Sie, wie Sie vorgehen und begründen Sie Ihr Vorgehen.',3,'entwurf',true,false,2,null,false,'PP-QS-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('134d0c9c-693e-52b6-b179-58b675aa3293','Der Trend zeigt an, dass der Prozess sich systematisch verändert, zum Beispiel durch Werkzeugverschleiß oder durch das Warmlaufen der Maschine. Ich unterbreche nicht sofort die Fertigung, weil die Teile noch in der Toleranz liegen, greife aber ein, bevor Ausschuss entsteht: Ich dokumentiere die Messwerte, informiere den Einrichter beziehungsweise den Vorgesetzten, prüfe die naheliegende Ursache – Schneidenverschleiß, Werkzeugstandzeit, Spannmittel –, korrigiere den Werkzeugkorrekturwert oder wechsle das Werkzeug und prüfe das erste Teil nach der Korrektur besonders sorgfältig. Anschließend beobachte ich die folgenden Teile in kürzeren Abständen. So bleibt der Prozess beherrscht und es entsteht kein Ausschuss.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Erkennt den Trend als Hinweis auf eine systematische Prozessveränderung", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt eine plausible Ursache (z. B. Werkzeugverschleiß, Temperaturgang)", "punkte": 1}, {"id": "k3", "beschreibung": "Beschreibt Dokumentation und Information der zuständigen Person", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt eine konkrete Korrekturmaßnahme (Korrekturwert, Werkzeugwechsel)", "punkte": 1}, {"id": "k5", "beschreibung": "Nennt die Nachkontrolle bzw. engere Prüfabstände nach der Korrektur", "punkte": 1}], "akzeptierte_synonyme": ["Standzeit", "Werkzeugkorrektur", "Einrichter informieren", "Erstteilprüfung"], "haeufige_fehler": ["Sofortiger Produktionsstopp ohne Begründung", "Abwarten bis Ausschuss entsteht"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('1c52a388-31f1-57fa-b8e0-ba3232ee1958','c13e443a-816b-5f18-9887-9b90c4c329fa','freitext','An Ihrer Maschine ist eine Schutzeinrichtung defekt. Der Auftrag ist eilig. Beschreiben Sie, wie Sie sich verhalten, und begründen Sie Ihr Verhalten.',2,'entwurf',true,false,2,null,false,'WISO-SU-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('1c52a388-31f1-57fa-b8e0-ba3232ee1958','Ich nehme die Maschine nicht in Betrieb beziehungsweise stelle sie still und sichere sie gegen unbefugtes Einschalten. Den Defekt melde ich unverzüglich dem Vorgesetzten und der Instandhaltung und dokumentiere ihn. Erst nach Instandsetzung und Freigabe der Schutzeinrichtung wird weitergearbeitet. Begründung: Schutzeinrichtungen dürfen nach Arbeitsschutzrecht und Unfallverhütungsvorschriften nicht umgangen oder außer Betrieb gesetzt werden. Der Zeitdruck eines Auftrags rechtfertigt keine Gefährdung von Leben und Gesundheit; außerdem trage ich als Beschäftigter die Pflicht, erkannte Mängel zu melden.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Maschine wird nicht betrieben bzw. stillgesetzt und gesichert", "punkte": 1}, {"id": "k2", "beschreibung": "Meldung an Vorgesetzten/Instandhaltung", "punkte": 1}, {"id": "k3", "beschreibung": "Weiterarbeit erst nach Instandsetzung und Freigabe", "punkte": 1}, {"id": "k4", "beschreibung": "Begründung mit Arbeitsschutz/Meldepflicht statt mit Termindruck", "punkte": 1}], "akzeptierte_synonyme": ["gegen Wiedereinschalten sichern", "Sicherheitseinrichtung nicht überbrücken", "Unfallverhütungsvorschrift"], "haeufige_fehler": ["Weiterarbeit mit besonderer Vorsicht", "Überbrücken der Schutzeinrichtung mit Zustimmung des Kollegen"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into berufe (id,traeger_id,kammer_id,bezeichnung,dauer_monate,bewertungsschluessel_id) values ('e0809c8d-f803-5a4f-a6e4-f8cbc762d0fc','4c89739f-2279-5917-9d6e-bc98fed1ffed','d61a7b9d-0f15-5d8d-98ac-4434a20b2ca4','Schweißtechnik – modulare Lehrgänge und Schweißerprüfung',null,'f117f69f-171f-5b40-9b50-728316b37d72') on conflict (id) do nothing;
