insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('9fddbbee-5b0c-5f15-9592-9f73dbdaa6bc','76502c0c-2196-5cb6-8d1b-27a7069a34ba','mc','Wodurch wird beim Metall-Schutzgasschweißen (MSG) die Schmelze vor der Umgebungsluft geschützt?',1,'entwurf',true,false,2,null,false,'SCH-VF-VE-101') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('99b8a1cf-703b-5196-b471-8b37a68ddb50','9fddbbee-5b0c-5f15-9592-9f73dbdaa6bc','Durch das Abdecken mit einer Keramikplatte',false,'Badsicherungen formen die Wurzel, ersetzen aber nicht den Gasschutz.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('3db16e06-4129-57b9-b6cb-ff7b5a2e7332','9fddbbee-5b0c-5f15-9592-9f73dbdaa6bc','Durch ein zugeführtes Schutzgas aus der Brennerdüse',true,'Das Schutzgas verdrängt Luftsauerstoff und Stickstoff von der Schmelze und verhindert so Poren und Versprödung.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('d7ad7236-1ad7-5ff7-893a-f7f63927335f','9fddbbee-5b0c-5f15-9592-9f73dbdaa6bc','Durch aufgestreutes Schweißpulver',false,'Das trifft auf das Unterpulverschweißen zu.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('f515b134-628a-5c31-8eaa-01330f0e07f0','9fddbbee-5b0c-5f15-9592-9f73dbdaa6bc','Durch Wasserdampf aus dem Werkstück',false,'Feuchtigkeit ist im Gegenteil eine Fehlerquelle.',4) on conflict (id) do nothing;
