insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('290abc38-b14c-54f8-b3b2-0f933454567a','76502c0c-2196-5cb6-8d1b-27a7069a34ba','mc','Was unterscheidet das WIG-Schweißen von den MSG-Verfahren?',2,'entwurf',true,false,2,null,false,'SCH-VF-VE-102') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('a047195c-3b0f-5070-b7ce-44c35b8f3d00','290abc38-b14c-54f8-b3b2-0f933454567a','Beim WIG-Schweißen schmilzt die Elektrode als Zusatzwerkstoff ab.',false,'Das beschreibt die MSG-Verfahren.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('b240bd1b-d3b3-56b3-a3cd-d1bc069bb361','290abc38-b14c-54f8-b3b2-0f933454567a','Beim WIG-Schweißen wird kein Schutzgas benötigt.',false,'WIG arbeitet gerade unter inertem Schutzgas.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('30098452-393a-5253-abcf-385f8bb2589e','290abc38-b14c-54f8-b3b2-0f933454567a','WIG ist nur für unlegierte Stähle geeignet.',false,'WIG wird gerade für nichtrostende Stähle und Aluminium geschätzt.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('b8c4359e-3893-52bc-9862-7b5e74f830e3','290abc38-b14c-54f8-b3b2-0f933454567a','WIG arbeitet ohne elektrischen Lichtbogen.',false,'Auch WIG ist ein Lichtbogenverfahren.',4) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('fb23393e-b2b0-5a54-a6b8-bc9d7fe9be01','290abc38-b14c-54f8-b3b2-0f933454567a','Beim WIG-Schweißen brennt der Lichtbogen an einer nicht abschmelzenden Wolframelektrode; der Zusatzwerkstoff wird getrennt zugeführt.',true,'Dadurch lassen sich Wärmeeinbringung und Zusatzwerkstoff unabhängig steuern – gut für Wurzellagen und dünne Bleche.',5) on conflict (id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('e2ff5483-9cce-5b20-8010-bc59b831da74','76502c0c-2196-5cb6-8d1b-27a7069a34ba','mc','Warum müssen basisch umhüllte Stabelektroden trocken gelagert und vor dem Einsatz gegebenenfalls rückgetrocknet werden?',2,'entwurf',true,false,2,null,false,'SCH-VF-VE-103') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('251bb975-97db-54e0-9fb8-d5d30e9aff97','e2ff5483-9cce-5b20-8010-bc59b831da74','Weil sie sonst zu schnell abschmelzen',false,'Die Abschmelzleistung hängt von Stromstärke und Elektrodentyp ab.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('97a40f8d-4faa-54f1-9006-1767499a45fb','e2ff5483-9cce-5b20-8010-bc59b831da74','Weil feuchte Elektroden nicht in den Halter passen',false,'Das ist kein technischer Zusammenhang.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('bc986d1d-68bd-5e30-9894-499a8dd71aeb','e2ff5483-9cce-5b20-8010-bc59b831da74','Weil Feuchtigkeit in der Umhüllung Wasserstoff in die Naht einbringt und Risse begünstigt',true,'Wasserstoffinduzierte Kaltrisse sind eine typische Folge feuchter Elektroden; die Rücktrocknung erfolgt nach Herstellerangabe.',3) on conflict (id) do nothing;
