insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('ab40c0bb-0957-59b6-b34d-c324a7a00d62','1. Poren – Feuchtigkeit, verschmutztes Blech, gestörter Gasschutz durch Zugluft oder verstopfte Düse. 2. Bindefehler – zu geringe Wärmeeinbringung, falsche Brennerführung, nicht entfernte Schlacke zwischen den Lagen. 3. Einbrandkerbe am Nahtübergang – zu hohe Stromstärke oder zu schnelle Schweißgeschwindigkeit, falscher Anstellwinkel. 4. Wurzelfehler beziehungsweise fehlender Durchschweißung – zu geringer Öffnungswinkel, zu großer Steg, zu wenig Wärme im Nahtgrund. Weitere zulässige Antworten: Risse durch Wasserstoff oder zu schnelle Abkühlung, Schlackeneinschlüsse, Nahtüberhöhung, Kantenversatz.','{"max_punkte": 8, "kriterien": [{"id": "k1", "beschreibung": "Erster Fehler korrekt benannt", "punkte": 1}, {"id": "k2", "beschreibung": "Passende Ursache zum ersten Fehler", "punkte": 1}, {"id": "k3", "beschreibung": "Zweiter Fehler korrekt benannt", "punkte": 1}, {"id": "k4", "beschreibung": "Passende Ursache zum zweiten Fehler", "punkte": 1}, {"id": "k5", "beschreibung": "Dritter Fehler korrekt benannt", "punkte": 1}, {"id": "k6", "beschreibung": "Passende Ursache zum dritten Fehler", "punkte": 1}, {"id": "k7", "beschreibung": "Vierter Fehler korrekt benannt", "punkte": 1}, {"id": "k8", "beschreibung": "Passende Ursache zum vierten Fehler", "punkte": 1}], "akzeptierte_synonyme": ["Gaseinschluss", "mangelnde Bindung", "Randkerbe", "Wurzelrückfall", "Kaltriss"], "haeufige_fehler": ["Fehler ohne Ursache genannt", "Verwechslung von Pore und Bindefehler"]}'::jsonb,8) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('8a13564a-b2f7-5d74-823b-6e1a22ae22bf','76dd60fa-cf97-5b6b-8566-128431f0d3b7','freitext','Beschreiben Sie die Gefährdungen beim Lichtbogenschweißen und ordnen Sie jeder Gefährdung eine Schutzmaßnahme zu.',2,'entwurf',true,false,2,null,false,'SCH-QS-F02') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('8a13564a-b2f7-5d74-823b-6e1a22ae22bf','Optische Strahlung: UV- und IR-Strahlung des Lichtbogens schädigen Augen und Haut – Schutzschild mit passendem Sichtfilter, geschlossene Schweißerkleidung, Abschirmung des Arbeitsplatzes gegenüber Dritten. Schweißrauche und Gase: gesundheitsschädlich bis krebserzeugend – Absaugung an der Entstehungsstelle, Lüftung, bei Bedarf Atemschutz. Hitze, Funken und glühende Teile: Verbrennungs- und Brandgefahr – Schweißerhandschuhe, schwer entflammbare Kleidung, brennbare Stoffe entfernen, Löschmittel und Brandwache, in brandgefährdeten Bereichen Schweißerlaubnis. Elektrische Gefährdung: Stromschlag besonders bei Nässe und in engen Räumen – einwandfreie Geräte und Leitungen, trockene isolierende Unterlage und Kleidung, Geräte mit geeigneter Leerlaufspannung, Prüfung der Anlage. Lärm und mechanische Gefährdungen beim Richten und Schleifen: Gehör- und Augenschutz.','{"max_punkte": 8, "kriterien": [{"id": "k1", "beschreibung": "Optische Strahlung als Gefährdung genannt", "punkte": 1}, {"id": "k2", "beschreibung": "Passende Schutzmaßnahme dazu", "punkte": 1}, {"id": "k3", "beschreibung": "Schweißrauche/Gase als Gefährdung genannt", "punkte": 1}, {"id": "k4", "beschreibung": "Passende Schutzmaßnahme dazu", "punkte": 1}, {"id": "k5", "beschreibung": "Brand- bzw. Verbrennungsgefahr genannt", "punkte": 1}, {"id": "k6", "beschreibung": "Passende Schutzmaßnahme dazu", "punkte": 1}, {"id": "k7", "beschreibung": "Elektrische Gefährdung genannt", "punkte": 1}, {"id": "k8", "beschreibung": "Passende Schutzmaßnahme dazu", "punkte": 1}], "akzeptierte_synonyme": ["Verblitzen der Augen", "Erfassung an der Entstehungsstelle", "Brandwache", "isolierende Unterlage", "Schweißerlaubnis"], "haeufige_fehler": ["Gefährdungen ohne zugeordnete Maßnahme", "Schutzschild als Schutz gegen Rauch genannt"]}'::jsonb,8) on conflict (frage_id) do nothing;
