insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('baf25f6a-cbd0-5e31-bab0-ecef50c0fccf','Holz ist hygroskopisch: Es nimmt bei hoher Luftfeuchte Feuchtigkeit auf und quillt, bei trockener Luft gibt es Feuchtigkeit ab und schwindet. Die Formänderung ist richtungsabhängig und tangential am größten, in Faserrichtung praktisch vernachlässigbar. Konstruktive Maßnahmen: Massivholzflächen werden nicht starr eingeleimt, sondern über Nut und Feder oder Langlöcher beweglich gehalten, damit sich die Breite ändern kann. Rückwände und Füllungen werden in Nuten lose eingeschoben statt verleimt. Weitere zulässige Antworten: Verwendung formstabiler Holzwerkstoffe für breite Flächen, Einbau bei passender Ausgleichsfeuchte, allseitig gleiche Oberflächenbehandlung.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Beschreibt Feuchteaufnahme und -abgabe als Ursache", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt Quellen und Schwinden bzw. die Richtungsabhängigkeit", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt eine zutreffende konstruktive Maßnahme", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt eine zweite zutreffende Maßnahme", "punkte": 1}], "akzeptierte_synonyme": ["hygroskopisch", "Ausgleichsfeuchte", "Nut und Feder", "Langloch", "gleitende Befestigung"], "haeufige_fehler": ["Behauptung, Holzwerkstoffe arbeiteten überhaupt nicht", "Starres Verleimen als Lösung genannt"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('924187fa-2ec8-5843-98f4-8b9f6d21746e','50b6e38b-c78e-5dbb-85bc-b1a81fadaabf','freitext','Beschreiben Sie vier Maßnahmen, mit denen Sie das Rückschlagrisiko an der Tischkreissäge verringern.',2,'entwurf',true,false,2,null,false,'TIS-FE-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('924187fa-2ec8-5843-98f4-8b9f6d21746e','1. Spaltkeil richtig eingestellt verwenden, damit sich der Schnittspalt nicht hinter dem Blatt schließt. 2. Schutzhaube und bei schmalen Werkstücken Schiebestock beziehungsweise Schiebeholz benutzen. 3. Werkstück sauber am Parallelanschlag führen, Anschlag bei Bedarf zurückversetzen, damit das Werkstück hinter dem Blatt frei liegt. 4. Nur gerade, saubere und spannungsarme Werkstücke schneiden, verzogenes Holz vorher richten. Ergänzend: scharfes, passendes Sägeblatt verwenden, nicht hinter dem Blatt stehen, Schnitthöhe nur wenig über Werkstückdicke einstellen.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Nennt den korrekt eingestellten Spaltkeil", "punkte": 1}, {"id": "k2", "beschreibung": "Nennt Schutzhaube und/oder Schiebestock", "punkte": 1}, {"id": "k3", "beschreibung": "Nennt sichere Werkstückführung am Anschlag", "punkte": 1}, {"id": "k4", "beschreibung": "Nennt eine weitere zutreffende Maßnahme", "punkte": 1}], "akzeptierte_synonyme": ["Schiebeholz", "scharfes Sägeblatt", "nicht in der Schnittlinie stehen", "verzogenes Holz vorrichten"], "haeufige_fehler": ["Handschuhe als Schutzmaßnahme genannt", "Entfernen des Spaltkeils zur besseren Sicht"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('abd3e9c6-e9a1-5d51-a3bb-8f68a1fc5705','b1e8d120-060e-5bc3-997c-0d99d5531a98','freitext','Ein Kunde beanstandet nach der Montage einen Einbauschrank, weil eine Tür schleift. Beschreiben Sie Ihr Vorgehen von der Reklamation bis zur Abnahme.',3,'entwurf',true,false,2,null,false,'TIS-WISO-F01') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('abd3e9c6-e9a1-5d51-a3bb-8f68a1fc5705','1. Reklamation sachlich aufnehmen, Termin vereinbaren und dem Kunden zusichern, dass der Mangel geprüft wird. 2. Vor Ort den Fehler eingrenzen: Fugenbild messen, prüfen, ob der Korpus im Lot und in der Waage steht, ob sich der Untergrund gesetzt hat oder ob die Bänder verstellt sind. 3. Ursache dokumentieren, auch mit Blick darauf, ob es sich um einen Ausführungsmangel oder um bauseitige Ursachen handelt. 4. Mangel beheben, in der Regel durch Ausrichten des Korpus und Justieren der Topfbänder in Höhe, Seite und Tiefe. 5. Funktion prüfen: Tür mehrfach öffnen und schließen, gleichmäßige Fuge kontrollieren. 6. Ergebnis gemeinsam mit dem Kunden abnehmen und die Nacharbeit schriftlich festhalten.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Sachliche Aufnahme der Reklamation und Terminvereinbarung", "punkte": 1}, {"id": "k2", "beschreibung": "Systematische Ursachensuche vor Ort", "punkte": 1}, {"id": "k3", "beschreibung": "Dokumentation der Ursache", "punkte": 1}, {"id": "k4", "beschreibung": "Fachgerechte Behebung (Ausrichten, Bänder justieren)", "punkte": 1}, {"id": "k5", "beschreibung": "Funktionsprüfung und Abnahme mit dem Kunden", "punkte": 1}], "akzeptierte_synonyme": ["Fugenbild", "Bänder einstellen", "Korpus ausrichten", "Nacharbeit dokumentieren"], "haeufige_fehler": ["Zurückweisung der Reklamation ohne Prüfung", "Behebung ohne Ursachenklärung"]}'::jsonb,5) on conflict (frage_id) do nothing;
